[[module CSS]]



:root {

    --sp_side-bar-width: 14.875rem;

    --sp_top-bar-height: 1.625rem;



    --embla-time: .775s;

    --embla-delay-1: .175s;

    --embla-delay-2: .625s;

    --embla-delay-3: .875s;

    --embla-delay-4: 1.25s;

}



/*--- THEME SIGMA RECONS --- */



#header {

    isolation: isolate;

    z-index: 3;



    background-image: linear-gradient(to bottom, rgb(0 0 0) 40%, rgb(252 252 252) 85%);

}

#header::before {

    transition: transform var(--embla-time) calc(var(--embla-delay-4) + .25s) cubic-bezier(.03,.57,.08,1);

}



#header-extra-div-2 {

    position: absolute;

    top: 0; left: 0;

    width: 100%; height: 100%;

    isolation: isolate;

    background-image: linear-gradient(to bottom, var(--sp_header-gradient-top-color) calc(var(--sp_header-gradient-top-stop) * var(--sp_header-height)), var(--sp_header-gradient-bottom-color) calc(var(--sp_header-gradient-bottom-stop) * var(--sp_header-height)) );

    z-index: -2;

    transition: opacity var(--embla-time) var(--embla-delay-4);

}

#header-extra-div-1 {

    position: absolute;

    top: 0; left: 0;

    width: 100%; height: 100%;

    background-image: repeating-linear-gradient(var(--sp_diagonal-stripes-angle), var(--sp_diagonal-stripes-color), var(--sp_diagonal-stripes-color) var(--sp_diagonal-stripes-width), transparent var(--sp_diagonal-stripes-width), transparent var(--sp_diagonal-stripes-gap));

    z-index: -1;

    transition: height var(--embla-time) var(--embla-delay-1) cubic-bezier(.09,.39,.22,1.01);

}



#header :is(h1,h2) {

    transition: padding-inline-start var(--embla-time) var(--embla-delay-1) cubic-bezier(.09,.39,.22,1.01);

}



#header h1 {

    a {

        display: grid;

        grid-template-areas: "stack";

        grid-template-rows: 1fr; grid-template-columns: 1fr;

    }

    a span { display: none; }

    a::before, a::after { grid-area: stack; align-self: center; }

    a::before { transition: opacity var(--embla-time) calc(var(--embla-delay-3) + var(--embla-time) + .125s); }

    a::after {

        content: "The SCP Foundation";

        text-shadow: none;

        font-size: var(--sp_header-title-size);

        font-family: "Trebuchet MS", InterVariable,RedactRect,Inter,BlinkMacSystemFont,Segoe UI,Roboto,Oxygen,Ubuntu,Cantarell,Fira Sans,Droid Sans,Helvetica Neue,sans-serif;

        opacity: 0;

        transition: opacity var(--embla-time) var(--embla-delay-3);

    }

}



#header h2 {

    span {

        display: grid;

        grid-template-areas: "stack2";

        grid-template-rows: 1fr; grid-template-columns: 1fr;

    }

    span::before, span::after { grid-area: stack2; align-self: center; }

    span::before { transition: opacity var(--embla-time) calc(var(--embla-delay-3) + var(--embla-time) + .125s); }

    span::after {

        content: "To Secure, Contain and Protect";

        font-size: var(--sp_header-subtitle-size);

        letter-spacing: 0.05vw;

        color: rgb(153 0 18);

        text-shadow: none;

        opacity: 0;

        transition: opacity var(--embla-time) var(--embla-delay-3);

    }

}



#top-bar {



    box-shadow: 0 .125rem 0.35rem rgb(0 0 0 /.25);

    isolation: isolate;

    transition: all var(--embla-time);

}

#top-bar::before {

    content: "";

    position: absolute;

    top: 0; left: 0;

    width: 100%; height: 100%;

    z-index: -1;



    background: #444;

    clip-path: inset(0 100%);

    transition: clip-path var(--embla-time);

}



#top-bar :is(.top-bar,.mobile-top-bar) > ul > li {

    > a { font-weight: bold; transition: font-weight var(--embla-time) var(--embla-delay-1); }

    > a::before { content: "["; opacity: 0; transition: opacity var(--embla-time) var(--embla-delay-1); }

    > a::after { content: "]"; opacity: 0; transition: opacity var(--embla-time) var(--embla-delay-1); }

}



#search-top-box-form input[type="submit"] {

    transition: filter var(--embla-time) var(--embla-delay-2), border-radius var(--embla-time) var(--embla-delay-2);

}





#side-bar {

    box-sizing: border-box;

    border: solid .05rem rgb(222 222 222 / 0);

    transition: padding var(--embla-time) var(--embla-delay-4), border-radius var(--embla-time) var(--embla-delay-4), border-color var(--embla-time) var(--embla-delay-4), box-shadow var(--embla-time) var(--embla-delay-4), left .25s 0s;



    .side-block {

        box-sizing: border-box;

        transition: inherit;

    }



    .heading { transition: all var(--embla-time) var(--embla-delay-4); }

}



/*---------------------------*/

/*--- THEME SWITCHER ---*/

/*---------------------------*/



:root:where(:has(#u-embla-switcher.folded)) {



#header-extra-div-1 { height: 0; }

#header-extra-div-2 { opacity: 0; }



#header::before { transform: scale(0); }



#header :is(h1,h2) { padding-inline-start: 0; }

#header h1 a::before { opacity: 0; }

#header h1 a::after { opacity: 1; }

#header h2 span::before { opacity: 0; }

#header h2 span::after { opacity: 1; }



#top-bar {

    box-shadow: 0 0 0rem rgb(0 0 0 /.25);

}

#top-bar::before {

    clip-path: inset(0);

}



#top-bar :is(.top-bar,.mobile-top-bar) > ul > li {

    > a { font-weight: normal; }

    > a::before { content: "["; opacity: 1;}

    > a::after { content: "]"; opacity: 1; }

}



#search-top-box-form input[type="submit"] {

    border-radius: 0;

    filter: grayscale(1);

}



#side-bar {

    padding: .75rem;

    border-color: rgb(222 222 222 / 1);



    .side-block {

        border-radius: 0;

        border-color: transparent;

        box-shadow: 0 0 0 #00000000;

    }

    .heading { color: rgb(0 0 0 / .95); border-bottom-color: rgb(171 171 171); }

}



--sp_rate-module-background: rgb(102 102 102);

--sp_rate-module-button-background: rgb(222 222 222);

--sp_rate-module-button-color: rgb(0 0 0);

--sp_rate-module-button-hover-background: rgb(237 237 237);

--sp_rate-module-button-hover-color: var(--sp_rate-module-button-color);

--sp_rate-module-sub-color: var(--sp_rate-module-button-background);



div.page-rate-widget-box, div.rate-box-with-credit-button {

    border-radius: 0;

    padding: 0;

    box-shadow: none;

}



}



/*--- LOGIC ---*/



.update-wrapper, .update-wrapper > li {

    padding: initial; margin: initial;

    display: contents;

    list-style: none;

}



.update-wrapper .foldable-list-container {

    pointer-events: none;

    a { pointer-events: auto; }

}



#u-embla-switcher.folded {

    .upd0 { display: block; }

    .upd1 { display: none; }

}

#u-embla-switcher.unfolded {

    .foldable-list-container, .upd0 { display: none; }

    .upd1 { display: block; }

}



.upd1 {

    position: relative;

    top: 0; opacity: 0;

    animation: final-fade calc(var(--embla-time) + .325s) cubic-bezier(.09,.58,.47,.99) calc(var(--embla-delay-4) + 2s);

    animation-fill-mode: forwards;

}



@keyframes final-fade {

    0% { opacity: 0; top: 2.5rem; }

    100% { opacity: 1; top: 0; }

}



/*-------------------*/

/*-------------------*/

/*-------------------*/



.vidlog {

    padding-block: .5rem; 

    strong { font-variant-numeric: tabular-nums; }

}



a.bibcite {

  display: inline-block;

  vertical-align: top;

  position: relative;

  top: -.5em;

  font-size: .775em;

}



.long-time {

    display: inline-block;

    position: relative;

    > strong:nth-child(1) { visibility: hidden; }

    > strong:nth-child(2) { position: absolute; inset-inline-end: 0;}

}



#page-title, #breadcrumbs { display: none; }

.meta-title { line-height: 1.15; }



.rate-container { text-align: end; }



.bibitems, .footnotes-footer { display: none; }



.embla-stinger {

    text-align: center;

    padding-block: 1.675rem;

    .collapsible-block-unfolded-link > a { pointer-events: none; }

}



